<?php require 'config.php';$u=require_login();page_start('Community',$u);heading('ASK. SHARE. COLLABORATE.','Better, together.','No question is too small. Every perspective belongs.');$id=(int)($_GET['topic']??0);if($id):$t=one('SELECT t.*,u.name,u.photo FROM topics t JOIN users u ON u.id=t.user_id WHERE t.id=?',[$id]);if(!$t):http_response_code(404);echo '<p>Discussion not found.</p>';else:?>
<a href="community.php">← All discussions</a><article class="card"><div style="display:flex;align-items:center;gap:12px;margin-bottom:12px;"><?=user_avatar($t, 42)?><div><h2 style="margin:0;"><?=e($t['title'])?></h2><p class="meta" style="margin:2px 0 0;"><?=e($t['name'])?> · <?=e($t['created_at'])?></p></div></div><div class="body-text"><?=e($t['body'])?></div></article><?php foreach(rows('SELECT r.*,u.name,u.photo FROM replies r JOIN users u ON u.id=r.user_id WHERE topic_id=? ORDER BY id',[$id]) as $r)echo '<div class="reply" style="display:flex;gap:12px;align-items:flex-start;">'.user_avatar($r, 32).'<div><strong>'.e($r['name']).'</strong><small> · '.e($r['created_at']).'</small><div class="body-text">'.e($r['body']).'</div></div></div>';?><form class="card" method="post" action="action.php"><?php csrf();?><input type="hidden" name="action" value="reply"><input type="hidden" name="id" value="<?=$id?>"><?php textarea('Add your reply','body');?><button class="button">Post reply →</button></form><?php endif;else:?>
<details><summary>+ Start a conversation</summary><form class="card" method="post" action="action.php"><?php csrf();?><input type="hidden" name="action" value="topic"><?php input('Discussion title','title');textarea('Your question or idea','body');?><button class="button">Publish discussion →</button></form></details>
<section class="card"><?php $topics=rows('SELECT t.*,u.name,u.photo,(SELECT COUNT(*) FROM replies r WHERE r.topic_id=t.id) replies FROM topics t JOIN users u ON u.id=t.user_id ORDER BY t.id DESC');foreach($topics as $t)echo '<a class="discussion-row" href="community.php?topic='.$t['id'].'">'.user_avatar($t, 34).'<div><h3>'.e($t['title']).'</h3><small>'.e($t['name']).' · '.e($t['created_at']).'</small></div><small>'.$t['replies'].' replies →</small></a>';if(!$topics)echo '<p>Be the first to start a conversation.</p>';?></section><?php endif;page_end(); ?>
